//! The `calimero:app` world, generated by `bindgen!`, mapped one-to-one onto `HostCore`.
//!
//! WASI interfaces are not generated here: `with` points them at wasmtime-wasi's and
//! wasmtime-wasi-http's bindings, and `wasi.rs` links the implementations.

use calimero_app_host::{self as host, CursorId};
use wasmtime::component::HasSelf;
use wasmtime::component::Linker;
use wasmtime::component::Resource;
use wasmtime::Result;

use crate::errors::denied;
use crate::StoreData;

wasmtime::component::bindgen!({
    // The same directory as `calimero_app_wit::WIT_DIR`; bindgen needs a literal.
    path: "../app-wit/wit",
    world: "calimero:app/app",
    imports: { default: trappable },
    with: {
        "wasi:io": wasmtime_wasi::p2::bindings::sync::io,
        "wasi:clocks": wasmtime_wasi::p2::bindings::clocks,
        "wasi:random": wasmtime_wasi::p2::bindings::random,
        "wasi:cli": wasmtime_wasi::p2::bindings::cli,
        "wasi:http": wasmtime_wasi_http::p2::bindings::http,
    },
    require_store_data_send: true,
});

use self::calimero::app::{action, blobs, context, events, rebuild, storage, types, xcall};

/// Links the eight `calimero:app` interfaces onto `StoreData`.
pub(crate) fn add_to_linker(linker: &mut Linker<StoreData>) -> Result<()> {
    let l = linker;
    types::add_to_linker::<StoreData, HasSelf<StoreData>>(l, |d| d)?;
    storage::add_to_linker::<StoreData, HasSelf<StoreData>>(l, |d| d)?;
    rebuild::add_to_linker::<StoreData, HasSelf<StoreData>>(l, |d| d)?;
    context::add_to_linker::<StoreData, HasSelf<StoreData>>(l, |d| d)?;
    events::add_to_linker::<StoreData, HasSelf<StoreData>>(l, |d| d)?;
    blobs::add_to_linker::<StoreData, HasSelf<StoreData>>(l, |d| d)?;
    xcall::add_to_linker::<StoreData, HasSelf<StoreData>>(l, |d| d)?;
    action::add_to_linker::<StoreData, HasSelf<StoreData>>(l, |d| d)?;
    Ok(())
}

impl From<host::InvocationKind> for types::InvocationKind {
    fn from(kind: host::InvocationKind) -> Self {
        match kind {
            host::InvocationKind::Call => Self::Call,
            host::InvocationKind::View => Self::View,
            host::InvocationKind::Action => Self::Action,
            host::InvocationKind::Timer => Self::Timer,
            host::InvocationKind::XcallDeliver => Self::XcallDeliver,
            host::InvocationKind::Init => Self::Init,
            host::InvocationKind::Migrate => Self::Migrate,
        }
    }
}

fn caller(caller: &host::Caller) -> types::Caller {
    match caller {
        host::Caller::Account(account) => types::Caller::Account(account.clone()),
        host::Caller::ApiKey { key_id, account } => types::Caller::ApiKey(types::ApiKeyCaller {
            key_id: key_id.clone(),
            account: account.clone(),
        }),
        host::Caller::Public => types::Caller::Public,
        host::Caller::System => types::Caller::System,
        host::Caller::App(app) => types::Caller::App(app.clone()),
    }
}

fn org_role(role: host::OrgRole) -> types::OrgRole {
    match role {
        host::OrgRole::Owner => types::OrgRole::Owner,
        host::OrgRole::Admin => types::OrgRole::Admin,
        host::OrgRole::Member => types::OrgRole::Member,
        host::OrgRole::Guest => types::OrgRole::Guest,
    }
}

fn audience(audience: types::Audience) -> host::Audience {
    match audience {
        types::Audience::All => host::Audience::All,
        types::Audience::Caller => host::Audience::Caller,
        types::Audience::Accounts(accounts) => host::Audience::Accounts(accounts),
        types::Audience::Team(team) => host::Audience::Team(team),
        types::Audience::OrgMembers(org) => host::Audience::OrgMembers(org),
        types::Audience::OrgAdmins(org) => host::Audience::OrgAdmins(org),
    }
}

/// A cursor handle carries the host core's cursor id as its rep; the component model's
/// handle table keeps the guest from forging one.
fn cursor(id: CursorId) -> Resource<storage::Cursor> {
    Resource::new_own(id.0)
}

impl types::Host for StoreData {}

impl storage::Host for StoreData {
    fn get(&mut self, key: Vec<u8>) -> Result<Option<Vec<u8>>> {
        self.host.storage_get(&key).map_err(denied)
    }

    fn put(&mut self, key: Vec<u8>, value: Vec<u8>) -> Result<()> {
        self.host.storage_put(&key, &value).map_err(denied)
    }

    fn delete(&mut self, key: Vec<u8>) -> Result<()> {
        self.host.storage_delete(&key).map_err(denied)
    }

    fn add(&mut self, key: Vec<u8>, delta: i64) -> Result<()> {
        self.host.storage_add(&key, delta).map_err(denied)
    }

    fn range(
        &mut self,
        start: Vec<u8>,
        end: Vec<u8>,
        reverse: bool,
    ) -> Result<Resource<storage::Cursor>> {
        self.host
            .range_open(&start, &end, reverse)
            .map(cursor)
            .map_err(denied)
    }
}

impl storage::HostCursor for StoreData {
    fn next(
        &mut self,
        this: Resource<storage::Cursor>,
        max: u32,
    ) -> Result<Vec<(Vec<u8>, Vec<u8>)>> {
        self.host
            .range_next(CursorId(this.rep()), max)
            .map_err(denied)
    }

    fn drop(&mut self, this: Resource<storage::Cursor>) -> Result<()> {
        self.host.range_close(CursorId(this.rep()));
        Ok(())
    }
}

impl rebuild::Host for StoreData {
    fn get(&mut self, key: Vec<u8>) -> Result<Option<Vec<u8>>> {
        self.host.rebuild_get(&key).map_err(denied)
    }

    fn put(&mut self, key: Vec<u8>, value: Vec<u8>) -> Result<()> {
        self.host.rebuild_put(&key, &value).map_err(denied)
    }

    fn delete(&mut self, key: Vec<u8>) -> Result<()> {
        self.host.rebuild_delete(&key).map_err(denied)
    }

    fn add(&mut self, key: Vec<u8>, delta: i64) -> Result<()> {
        self.host.rebuild_add(&key, delta).map_err(denied)
    }

    fn range(
        &mut self,
        start: Vec<u8>,
        end: Vec<u8>,
        reverse: bool,
    ) -> Result<Resource<storage::Cursor>> {
        self.host
            .rebuild_range(&start, &end, reverse)
            .map(cursor)
            .map_err(denied)
    }
}

impl context::Host for StoreData {
    fn caller(&mut self) -> Result<types::Caller> {
        Ok(caller(self.host.caller()))
    }

    fn app_id(&mut self) -> Result<String> {
        Ok(self.host.app_id().to_owned())
    }

    fn app_owner(&mut self) -> Result<String> {
        Ok(self.host.app_owner())
    }

    fn org(&mut self) -> Result<Option<String>> {
        Ok(self.host.org())
    }

    fn org_role(&mut self, account: String) -> Result<Option<types::OrgRole>> {
        Ok(self.host.org_role(&account).map(org_role))
    }

    fn org_role_strict(&mut self, account: String) -> Result<Option<types::OrgRole>> {
        self.host
            .org_role_strict(&account)
            .map(|role| role.map(org_role))
            .map_err(denied)
    }

    fn orgs_of(&mut self, account: String) -> Result<Vec<types::OrgMembership>> {
        Ok(self
            .host
            .orgs_of(&account)
            .into_iter()
            .map(|(org, role)| types::OrgMembership {
                org,
                role: org_role(role),
            })
            .collect())
    }

    fn in_team(&mut self, account: String, team: String) -> Result<bool> {
        Ok(self.host.in_team(&account, &team))
    }

    fn applied_index(&mut self) -> Result<u64> {
        Ok(self.host.applied_index())
    }

    fn unique_id(&mut self) -> Result<String> {
        self.host.unique_id().map_err(denied)
    }

    fn start_action(
        &mut self,
        method: String,
        args: Vec<u8>,
    ) -> Result<std::result::Result<String, String>> {
        self.host.start_action(&method, &args).map_err(denied)
    }
}

impl events::Host for StoreData {
    fn emit(&mut self, event: types::Event) -> Result<std::result::Result<(), String>> {
        let event = host::Event {
            name: event.name,
            data: event.data,
            audience: audience(event.audience),
        };
        self.host.emit(event).map_err(denied)
    }
}

impl blobs::Host for StoreData {
    fn info(&mut self, id: String) -> Result<Option<types::BlobInfo>> {
        let info = self.host.blobs_info(&id).map_err(denied)?;
        Ok(info.map(|info| types::BlobInfo {
            size: info.size,
            sha256: info.sha256,
            mime: info.mime,
        }))
    }

    fn grant(&mut self, id: String, ttl_seconds: u32) -> Result<String> {
        self.host.blobs_grant(&id, ttl_seconds).map_err(denied)
    }
}

impl xcall::Host for StoreData {
    fn send(
        &mut self,
        app: String,
        method: String,
        args: Vec<u8>,
    ) -> Result<std::result::Result<(), String>> {
        self.host
            .xcall_send(&app, &method, &args)
            .map(Ok)
            .map_err(denied)
    }
}

impl action::Host for StoreData {
    fn key(&mut self) -> Result<String> {
        self.host.action_key().map_err(denied)
    }

    fn view(
        &mut self,
        method: String,
        args: Vec<u8>,
    ) -> Result<std::result::Result<Vec<u8>, String>> {
        self.host.action_view(&method, &args).map_err(denied)
    }

    fn call(
        &mut self,
        method: String,
        args: Vec<u8>,
    ) -> Result<std::result::Result<Vec<u8>, String>> {
        self.host.action_call(&method, &args).map_err(denied)
    }
}
